import{_ as e,c as a,o as r,a0 as i}from"./chunks/framework.oTSD2LDJ.js";const g=JSON.parse('{"title":"关于 Uniquenium","description":"","frontmatter":{"title":"关于 Uniquenium","layout":"doc","editLink":true},"headers":[],"relativePath":"about.md","filePath":"zh/about.md"}'),n={name:"about.md"};function l(o,t,s,h,d,u){return r(),a("div",null,t[0]||(t[0]=[i(`<h1 id="关于-uniquenium" tabindex="-1">关于 Uniquenium <a class="header-anchor" href="#关于-uniquenium" aria-label="Permalink to &quot;关于 Uniquenium&quot;">​</a></h1><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p><strong>Uniquenium</strong> 是一款开源的桌面自定义工具，致力于可定制的桌面环境。项目名称由 &quot;Unique&quot;（独特）+ &quot;Quantum&quot;（量子）组合而来，寓意着为每位用户创造独一无二的桌面体验。</p><p>我们相信，桌面不只是工作的起点，更是表达个性的画布。</p><ul><li>🎨 <strong>精美</strong>：现代 Fluent 设计语言，深浅色主题无缝切换</li><li>🧩 <strong>灵活</strong>：组件化架构，随心所欲搭配你的桌面</li><li>🔌 <strong>开放</strong>：插件与模板系统，无限扩展可能</li><li>💝 <strong>免费</strong>：完全开源免费，社区驱动开发</li></ul><h2 id="贡献者" tabindex="-1">贡献者 <a class="header-anchor" href="#贡献者" aria-label="Permalink to &quot;贡献者&quot;">​</a></h2><ul><li><a href="https://github.com/admibrill" target="_blank" rel="noreferrer">Admibrill</a></li></ul><p>从最初的简单面板原型，到现在拥有完整控件库、插件系统、模板机制的成熟项目，离不开每一位贡献者的努力。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>界面渲染</td><td><strong>QML / Qt Quick</strong></td><td>声明式 UI 语言，硬件加速渲染</td></tr><tr><td>核心逻辑</td><td><strong>C++17 / Qt6</strong></td><td>纯 C++ 实现，高性能与跨平台</td></tr><tr><td>UI 控件库</td><td><strong>UniDesk</strong></td><td>自研 30+ 控件，基于 LingmoUI 设计</td></tr><tr><td>系统交互</td><td><strong>Win32 API / QHotkey</strong></td><td>无边框窗口、全局热键、壁纸设置等</td></tr><tr><td>构建系统</td><td><strong>CMake + ECM</strong></td><td>跨平台编译与打包</td></tr><tr><td>文档站点</td><td><strong>VitePress</strong></td><td>基于 Vue 的静态文档生成器</td></tr><tr><td>图标资源</td><td><strong>Remix Icons</strong></td><td>开源中性风格图标库</td></tr></tbody></table><h2 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to &quot;致谢&quot;">​</a></h2><p>Uniquenium 离不开以下开源项目和个人的支持：</p><h3 id="核心贡献者" tabindex="-1">核心贡献者 <a class="header-anchor" href="#核心贡献者" aria-label="Permalink to &quot;核心贡献者&quot;">​</a></h3><ul><li>💻 <a href="https://github.com/admibrill" target="_blank" rel="noreferrer">Admibrill</a> - 项目发起者与核心开发者</li></ul><h3 id="开源项目" tabindex="-1">开源项目 <a class="header-anchor" href="#开源项目" aria-label="Permalink to &quot;开源项目&quot;">​</a></h3><ul><li>🎨 <a href="https://github.com/LingmoOS/LingmoUI" target="_blank" rel="noreferrer">LingmoUI</a> - UniDesk 控件库的设计基础</li><li>⌨️ <a href="https://github.com/Skycoder42/QHotkey" target="_blank" rel="noreferrer">QHotkey</a> - 跨平台全局热键支持</li><li>🔤 <a href="https://www.remixicon.cn" target="_blank" rel="noreferrer">Remix Icons</a> - 精美的开源图标库</li><li>🔢 <a href="https://github.com/ArashPartow/exprtk" target="_blank" rel="noreferrer">ExprTk</a> - 数学表达式解析引擎</li><li>⚡ <a href="https://www.qt.io/" target="_blank" rel="noreferrer">Qt6</a> - 强大的跨平台 C++ 应用框架</li><li>📦 <a href="https://invent.kde.org/frameworks/extra-cmake-modules" target="_blank" rel="noreferrer">ECM</a> - Extra CMake Modules</li></ul><h3 id="社区与用户" tabindex="-1">社区与用户 <a class="header-anchor" href="#社区与用户" aria-label="Permalink to &quot;社区与用户&quot;">​</a></h3><p>感谢每一位提交 Issue、PR、翻译文档、分享模板的社区成员 ❤️</p><p>QQ群: 1107749494 Discord: <a href="https://discord.gg/Cqq9sRkrW2" target="_blank" rel="noreferrer">Uniquenium</a></p><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><h3 id="代码许可" tabindex="-1">代码许可 <a class="header-anchor" href="#代码许可" aria-label="Permalink to &quot;代码许可&quot;">​</a></h3><p>Uniquenium 项目代码遵循 <strong>GNU General Public License v3.0</strong> 开源协议发布：</p><blockquote><p>你可以自由地运行、研究、分享和改进本软件。修改后的衍生作品<strong>必须</strong>以相同协议开源。</p></blockquote><p>完整协议文本：<a href="https://github.com/Uniquenium/Uniquenium/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a></p><h3 id="文档许可" tabindex="-1">文档许可 <a class="header-anchor" href="#文档许可" aria-label="Permalink to &quot;文档许可&quot;">​</a></h3><p>本文档（Docs 仓库）遵循 <strong>Creative Commons Attribution-ShareAlike 4.0 International (CC BY-SA 4.0)</strong> 协议：</p><blockquote><p>你可以自由分享（复制、分发、传播）和改编（修改、商用）本文档，只需：</p><ul><li><strong>署名</strong>：给出适当的署名，提供协议链接</li><li><strong>相同方式共享</strong>：改编后的内容必须以相同协议发布</li></ul></blockquote><h2 id="版本信息" tabindex="-1">版本信息 <a class="header-anchor" href="#版本信息" aria-label="Permalink to &quot;版本信息&quot;">​</a></h2><p>你可以通过以下方式查看版本：</p><ul><li><strong>程序内</strong>：设置 → 关于 → 版本号</li><li><strong>代码中</strong>：<div class="language-qml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">qml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> UniDesk</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 通过 UniDeskTools 获取版本号</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">var major = UniDeskTools.getModuleVersionMajor()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">var minor = UniDeskTools.getModuleVersionMinor()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">var patch = UniDeskTools.getModuleVersionPatch()</span></span></code></pre></div></li></ul><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to &quot;联系我们&quot;">​</a></h2><table tabindex="0"><thead><tr><th>渠道</th><th>链接</th><th>用途</th></tr></thead><tbody><tr><td>GitHub 仓库</td><td><a href="https://github.com/Uniquenium/Uniquenium" target="_blank" rel="noreferrer">Uniquenium/Uniquenium</a></td><td>源代码、Issue、PR</td></tr><tr><td>文档仓库</td><td><a href="https://github.com/Uniquenium/Docs" target="_blank" rel="noreferrer">Uniquenium/Docs</a></td><td>本站文档源码</td></tr><tr><td>DeepWiki</td><td><a href="https://deepwiki.com/Uniquenium/Uniquenium" target="_blank" rel="noreferrer">deepwiki.com/Uniquenium</a></td><td>交互式代码文档</td></tr><tr><td>Issue 反馈</td><td><a href="https://github.com/Uniquenium/Uniquenium/issues/new/choose" target="_blank" rel="noreferrer">新建 Issue</a></td><td>Bug 报告 / 功能建议</td></tr></tbody></table><h2 id="贡献指南" tabindex="-1">贡献指南 <a class="header-anchor" href="#贡献指南" aria-label="Permalink to &quot;贡献指南&quot;">​</a></h2><p>我们热情欢迎各种形式的贡献！</p><h3 id="适合新手的贡献方式" tabindex="-1">适合新手的贡献方式 <a class="header-anchor" href="#适合新手的贡献方式" aria-label="Permalink to &quot;适合新手的贡献方式&quot;">​</a></h3><ol><li>📝 <strong>完善文档</strong>：修复错别字、补充说明、翻译英文文档</li><li>🐛 <strong>报告 Bug</strong>：提交详细的复现步骤和环境信息</li><li>🎨 <strong>分享模板</strong>：导出你设计的精美页面模板给大家使用</li><li>💡 <strong>提出建议</strong>：分享你的使用体验和改进想法</li></ol><h3 id="代码贡献流程" tabindex="-1">代码贡献流程 <a class="header-anchor" href="#代码贡献流程" aria-label="Permalink to &quot;代码贡献流程&quot;">​</a></h3><ol><li>Fork 仓库到你的账号</li><li>创建新分支：<code>git checkout -b feature/your-feature</code></li><li>提交代码：<code>git commit -m &quot;feat: 添加你的功能&quot;</code></li><li>推送分支：<code>git push origin feature/your-feature</code></li><li>打开 Pull Request，等待代码审查</li></ol><h3 id="提交规范" tabindex="-1">提交规范 <a class="header-anchor" href="#提交规范" aria-label="Permalink to &quot;提交规范&quot;">​</a></h3><ul><li>feat: 新功能</li><li>fix: Bug 修复</li><li>docs: 文档更新</li><li>style: 代码格式调整（不影响功能）</li><li>refactor: 重构</li><li>perf: 性能优化</li><li>test: 测试相关</li><li>chore: 构建/工具链相关</li></ul><h2 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to &quot;路线图&quot;">​</a></h2><p>想知道我们正在做什么？查看公开的 <a href="https://github.com/Uniquenium/Uniquenium/blob/main/TODO.md" target="_blank" rel="noreferrer">主程序TODO 列表</a>和 <a href="https://github.com/Uniquenium/OfficialPlugin/blob/main/TODO.md" target="_blank" rel="noreferrer">插件TODO 列表</a>，包括：</p><ul><li>✅ Linux 平台支持（开发中）</li><li>✅ 更多官方插件组件（计算器、截屏、天气等）</li></ul><hr><p><strong>Made with ❤️ by Uniquenium Development Team</strong></p><blockquote><p>「让桌面，回归你想要的样子。」</p></blockquote>`,46)]))}const b=e(n,[["render",l]]);export{g as __pageData,b as default};
